cd ~/cp-roles/implementation-swi-prolog/programs/swi-prolog && SP=/private/tmp/claude-501/-HOME-chris-source-esoteric-absys/b126b1d8-c269-4983-bbfc-deaa2e7fcf81/scratchpad
for f in P01b P01c P01c-occurs-check P03a P03b P03c P03d P03e P03f; do
  if grep -q '^rev(' plain/$f.pl; then tab='conc/3, rev/2'; else tab='conc/3'; fi
  awk -v tab="$tab" '
    /^% The same text in plain, coroutines, constraints and session; tabling.s$/ { print "% The tabling text: the plain text with the relations the problem defines"; next }
    /^% text differs only by its table directive \(programs\/swi-prolog\/README.md\)\.$/ { print "% tabled, as in every tabling program here (programs/swi-prolog/README.md)."; next }
    /^% END PROVENANCE$/ { print "%   tabling: the table/1 directive on the problem'"'"'s relations (SWI-Prolog"; print "%     manual, section 7 \"Tabled execution (SLG resolution)\")" }
    /^% conc\(a, b, c\): c is a followed by b$/ { print ":- table " tab "."; print "" }
    { print }' plain/$f.pl > tabling/$f.pl
done
diff plain/P03f.pl tabling/P03f.pl; diff plain/P01c-occurs-check.pl tabling/P01c-occurs-check.pl
